import { component$ } from "@qwik.dev/core";
import { StampShader } from "./stamp-shader";
import {
  rubricGradeStampAsset,
  rubricGradeTier,
} from "../../utils/rubric-feedback";

interface GradeStampProps {
  grade: string;
  score: number;
  color: string;
  size?: "compact" | "report";
  animated?: boolean;
}

/** A complete grade-specific impression, recolored by the active theme. */
export const GradeStamp = component$<GradeStampProps>((props) => {
  const tier = rubricGradeTier(props.grade);
  const asset = rubricGradeStampAsset(props.grade);
  const highest = props.grade.trim().toUpperCase() === "A+";
  return (
    <div
      class={[
        "rubric-grade-stamp",
        `rubric-grade-stamp--${props.size ?? "compact"}`,
        `rubric-grade-stamp--${tier}`,
        { "rubric-grade-stamp--highest": highest },
        { "rubric-grade-stamp--animated": props.animated },
      ]}
      style={{
        color: props.color,
        "--rubric-stamp-image": `url("${asset}")`,
      }}
      role="img"
      aria-label={`Overall grade ${props.grade}, ${props.score} of 100`}
    >
      {props.animated && (tier === "a" || tier === "b") && (
        <StampShader
          key={props.grade}
          strength={highest ? 3 : tier === "a" ? 2 : 1}
        />
      )}
    </div>
  );
});
import { component$, useSignal } from "@qwik.dev/core";
import type { Meta, StoryObj } from "storybook-framework-qwik";
import { WorkflowStamp } from "./workflow-stamp";

const WorkflowPreview = component$<{
  kind: "filed" | "revised";
  overlay?: boolean;
}>((props) => {
  const replay = useSignal(0);
  return (
    <div class="paper-sheet p-8">
      <button class="btn-paper" onClick$={() => replay.value++}>
        Replay {props.kind} stamp
      </button>
      <div
        key={replay.value}
        class={props.overlay ? "approval-stamp-overlay" : "mt-8"}
      >
        <WorkflowStamp kind={props.kind} />
      </div>
    </div>
  );
});

export default {
  title: "Editorial/Workflow stamps",
  component: WorkflowStamp,
  parameters: { layout: "centered" },
} satisfies Meta<typeof WorkflowStamp>;
type Story = StoryObj<typeof WorkflowStamp>;
export const Filed: Story = { render: () => <WorkflowPreview kind="filed" /> };
export const Revised: Story = {
  render: () => <WorkflowPreview kind="revised" />,
};
export const AcceptedRevision: Story = {
  render: () => <WorkflowPreview kind="revised" overlay />,
};
