/** Locally generated, transparent artwork. The manuscript always retains its text. */
const INITIAL_ASSET_ROOT = "/assets/illuminated-initials";

export const ILLUMINATED_INITIALS = Object.freeze(
  Object.fromEntries(
    "REDACTED".split("").map((letter) => [
      letter.toUpperCase(),
      `${INITIAL_ASSET_ROOT}/${letter}.webp`,
    ]),
  ) as Readonly<Record<string, string>>,
);

/** The complete 30-piece collection, including four alternate engravings. */
export const ILLUMINATED_INITIAL_ARTWORK = Object.freeze([
  ...Object.values(ILLUMINATED_INITIALS),
  ...["a", "i", "t", "w"].map(
    (letter) => `${INITIAL_ASSET_ROOT}/${letter}-alt.webp`,
  ),
]);

export interface OpeningInitial {
  /** UTF-16 offsets, matching DOM and ProseMirror text positions. */
  from: number;
  to: number;
  glyph: string;
  artwork: string | null;
}

const segmenter = new Intl.Segmenter(undefined, { granularity: "grapheme" });
const openingPunctuation = /^[\s“‘"'«‹「『(\[{¿¡]+$/u;

/** Only an actual ASCII letter has matching artwork: É and E◌́ remain É/E◌́. */
export function openingInitial(text: string): OpeningInitial | null {
  for (const { segment, index } of segmenter.segment(text)) {
    if (openingPunctuation.test(segment)) continue;
    if (!/^[\p{L}\p{N}]/u.test(segment)) return null;
    return {
      from: index,
      to: index + segment.length,
      glyph: segment,
      artwork: /^[a-z]$/i.test(segment)
        ? (ILLUMINATED_INITIALS[segment.toUpperCase()] ?? null)
        : null,
    };
  }
  return null;
}
import { Extension } from "@tiptap/core";
import type { Node as ProseMirrorNode } from "@tiptap/pm/model";
import { Plugin, PluginKey } from "@tiptap/pm/state";
import { Decoration, DecorationSet } from "@tiptap/pm/view";
import { openingInitial } from "../../../utils/illuminated-initials";

interface InitialLocation {
  paragraphFrom: number;
  paragraphTo: number;
  from: number;
  to: number;
  artwork: string | null;
}

interface IlluminatedInitialState {
  initial: InitialLocation | null;
  loaded: ReadonlySet<string>;
  decorations: DecorationSet;
}

export const illuminatedInitialPluginKey =
  new PluginKey<IlluminatedInitialState>("twyneIlluminatedInitial");

function findInitial(doc: ProseMirrorNode): InitialLocation | null {
  let initial: InitialLocation | null = null;
  let foundParagraph = false;
  doc.forEach((node, offset) => {
    if (foundParagraph || node.type.name !== "paragraph") return;
    foundParagraph = true;
    // Leaf atoms occupy one position, so text offsets still match the document.
    // An opening image/note/equation must not illuminate unrelated later text.
    const text = node.textBetween(0, node.content.size, "", "\ufffc");
    const opening = openingInitial(text);
    if (!opening) return;
    initial = {
      paragraphFrom: offset,
      paragraphTo: offset + node.nodeSize,
      from: offset + 1 + opening.from,
      to: offset + 1 + opening.to,
      artwork: opening.artwork,
    };
  });
  return initial;
}

function decorate(
  doc: ProseMirrorNode,
  loaded: ReadonlySet<string>,
): IlluminatedInitialState {
  const initial = findInitial(doc);
  if (!initial)
    return { initial, loaded, decorations: DecorationSet.empty };
  const ready = initial.artwork && loaded.has(initial.artwork);
  return {
    initial,
    loaded,
    decorations: DecorationSet.create(doc, [
      Decoration.node(initial.paragraphFrom, initial.paragraphTo, {
        class: "twyne-illuminated-paragraph",
      }),
      Decoration.inline(initial.from, initial.to, {
        nodeName: "span",
