  useVisibleTask$(async ({ cleanup }) => {
    let disposed = false;
    let editor: import("@tiptap/core").Editor | undefined;
    cleanup(() => {
      disposed = true;
      editor?.destroy();
    });
    const [{ Editor }, { StarterKit }, { IlluminatedInitial }] =
      await Promise.all([
        import("@tiptap/core"),
        import("@tiptap/starter-kit"),
        import("./extensions/illuminated-initial"),
      ]);
    if (disposed || !mount.value) return;
    editor = new Editor({
      element: mount.value,
      extensions: [StarterKit, IlluminatedInitial],
      content: props.content ?? `<p>${prose}</p><p>The manuscript remains editable. Change its opening letter to try another initial, then undo to restore it.</p>`,
      editorProps: {
        attributes: { role: "textbox", "aria-label": "Illuminated manuscript", "aria-multiline": "true" },
      },
    });
  });
  return (
    <div class="paper-sheet" style="width: min(48rem, 100%); padding: clamp(1.25rem, 5vw, 3rem);">
      <div class="twyne-editor" ref={mount} />
    </div>
  );
});

const InitialCollection = component$(() => (
  <div class="paper-sheet" style="padding: 2rem; max-width: 70rem;">
    <div style="display: flex; flex-wrap: wrap; gap: 1.5rem;">
      {ILLUMINATED_INITIAL_ARTWORK.map((url) => {
        const name = url.split("/").pop()!.replace(".webp", "");
        const label = name.endsWith("-alt")
          ? `${name[0].toUpperCase()} alternate`
          : name.toUpperCase();
        return (
          <figure key={url} style="margin: 0; width: 8rem; text-align: center;">
            <img src={url} width={128} height={128} alt={`Illuminated ${label}`} style="object-fit: contain;" />
            <figcaption style="margin-top: 0.5rem; font-family: var(--font-mono); font-size: 0.8rem;">{label}</figcaption>
          </figure>
        );
      })}
    </div>
  </div>
));

