import { component$, Slot, useSignal } from "@qwik.dev/core";

/**
 * A real wooden die presses the projected impression into the paper.
 * The mark is readable before the optional image loads, and remains if it fails.
 * Mount/key this component only for a new event, never for routine repaints.
 */
export const StampPress = component$<{ animated?: boolean }>((props) => {
  const toolReady = useSignal(false);

  return (
    <span
      class={[
        "ink-stamp",
        { "ink-stamp--pressing": props.animated && toolReady.value },
      ]}
      aria-hidden="true"
    >
      <span class="ink-stamp__imprint">
        <Slot />
      </span>
      {props.animated && (
        <>
          <span class="ink-stamp__contact-shadow" />
          <img
            class="ink-stamp__tool"
            src="/assets/stamp-press/walnut-stamp.webp"
            width={768}
            height={768}
            alt=""
            draggable={false}
            onLoad$={() => (toolReady.value = true)}
          />
        </>
      )}
    </span>
  );
});
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background-color: var(--color-paper-soft);
  background-image: url("/assets/rubric-proof-fibers.png");
  background-size: 24rem 24rem;
}
.rubric-proof::after {
  position: absolute;
  z-index: 0;
  inset: 0;
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--color-ink-muted) 10%, transparent);
  content: "";
  opacity: 0.6;
  pointer-events: none;
}
.rubric-proof > * {
  position: relative;
  z-index: 1;
}
.rubric-proof--fresh {
  animation: rubric-proof-settle 380ms cubic-bezier(0.16, 1, 0.3, 1) both;
  transform-origin: top center;
}

/* The same physical die prints workflow acknowledgements and verdicts.
   Only the brief press moves; the final ink stays put and remains readable. */
.ink-stamp {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  isolation: isolate;
  pointer-events: none;
}
.ink-stamp__imprint {
  position: absolute;
  inset: 0;
  display: block;
  opacity: 0.88;
}
.ink-stamp__tool {
  position: absolute;
  z-index: 3;
  top: -70%;
  left: -32.5%;
  display: block;
  width: 165%;
  max-width: none;
  height: auto;
  opacity: 0;
  object-fit: contain;
  transform-origin: 50% 82%;
  user-select: none;
}
.ink-stamp__contact-shadow {
  position: absolute;
  z-index: 2;
  inset: 26% 16% 18%;
  border-radius: 50%;
  background: #20150c;
  filter: blur(5px);
  opacity: 0;
}
.ink-stamp--pressing .ink-stamp__tool {
  animation: stamp-die-press 500ms linear both;
}
.ink-stamp--pressing .ink-stamp__imprint {
  animation: stamp-ink-settle 500ms linear both;
}
.ink-stamp--pressing .ink-stamp__contact-shadow {
  animation: stamp-contact-shadow 500ms linear both;
}

.rubric-grade-stamp {
  --stamp-rotation: -4deg;
  position: relative;
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  color: var(--color-ink);
  transform: rotate(var(--stamp-rotation));
  transform-origin: center;
  isolation: isolate;
}
.rubric-grade-stamp__mark {
  position: absolute;
  inset: 0;
  background: currentColor;
  -webkit-mask: var(--rubric-stamp-image) center / contain no-repeat;
  mask: var(--rubric-stamp-image) center / contain no-repeat;
}
.rubric-grade-stamp--compact {
  width: 5.5rem;
  height: 5.5rem;
}
.rubric-grade-stamp--report {
  width: 9rem;
  height: 9rem;
}
.rubric-grade-stamp--a {
  --stamp-rotation: -5deg;
}
.rubric-grade-stamp--b {
  --stamp-rotation: 3deg;
}
.rubric-grade-stamp--c {
  --stamp-rotation: -2deg;
}
.rubric-grade-stamp--revise {
  --stamp-rotation: 4deg;
}
.rubric-grade-stamp--animated {
  z-index: 2;
}
/* Give the handle room above the compact mark, without affecting layout. */
.rubric-proof:has(.rubric-grade-stamp--animated) {
  overflow: visible;
