      exportedAt: new Date().toISOString(),
      title: p.title,
      brief: p.brief ?? null,
      folios: p.folios ?? [],
      content: {
        html: p.html,
        format: "typst",
        typstSource: p.typstSource ?? htmlToTypst(p.html),
      },
    },
    null,
    2,
  );
}

