.twyne-editor .ProseMirror-gapcursor {
  display: none;
  pointer-events: none;
  position: absolute;
}

.twyne-editor .ProseMirror-gapcursor::after {
  content: "";
  display: block;
  position: absolute;
  top: -2px;
  width: 1.25rem;
  border-top: 2px solid var(--color-vermilion);
  animation: twyne-gapcursor-blink 1.1s steps(2, start) infinite;
}

@keyframes twyne-gapcursor-blink {
  to {
    visibility: hidden;
  }
}

@media (prefers-reduced-motion: reduce) {
  .twyne-editor .ProseMirror-gapcursor::after {
    animation: none;
  }
}

.twyne-editor .ProseMirror-focused .ProseMirror-gapcursor,
.twyne-editor .ProseMirror-gapcursor:focus {
  display: block;
}

/* Page ornaments stay outside contentEditable. Nine-slice frames retain their
 * corners when a continuous manuscript grows or the sheet changes orientation. */
.page-canvas {
  container: manuscript-page / inline-size;
}
.page-canvas.has-ornate-border {
  --ornament-clearance: 5rem;
}
.manuscript-border {
  position: absolute;
  inset: 0.625rem;
  z-index: 0;
  border: 1px solid var(--color-paper-3);
  pointer-events: none;
  user-select: none;
}
.manuscript-border--ornate {
  inset: 1.5rem;
  border: 3rem solid transparent;
  border-image-slice: 320;
  border-image-repeat: stretch;
}
.page-canvas .ProseMirror {
  column-count: var(--manuscript-columns, 1);
  column-gap: var(--manuscript-column-gap, 1.5rem);
  column-fill: balance;
  orphans: 2;
  widows: 2;
}
.page-canvas .ProseMirror > h1 {
  column-span: all;
}
@container manuscript-page (width < 40rem) {
  .page-canvas .ProseMirror {
    column-count: 1;
  }
  .manuscript-border--ornate {
    inset: 0.625rem;
    border-width: 2rem;
  }
}

@media (max-width: 639px) {
  .page-canvas.has-ornate-border {
    --ornament-clearance: 2.75rem;
  }
}

/* ── Tiptap manuscript page ──────────────────────────────── */
.twyne-editor .ProseMirror {
  outline: none;
  min-height: 60vh;
  font-family: var(--font-serif);
  font-size: 1.125rem;
  line-height: 1.8;
  color: var(--color-ink);
  font-feature-settings:
    "kern",
    "liga",
    "onum" 1;
}

.twyne-editor .ProseMirror p {
  margin-bottom: 0.45em;
  text-align: justify;
  hyphens: auto;
  -webkit-hyphens: auto;
}

/* The opening glyph remains manuscript text. Its transparent engraving is a
 * view-only background; slow/missing artwork keeps the ordinary drop cap. */
.twyne-editor .ProseMirror[data-opening-initial-size="small"] {
  --twyne-initial-size: 3em;
  --twyne-initial-bound: 3.5rem;
}

.twyne-editor .ProseMirror[data-opening-initial-size="medium"] {
  --twyne-initial-size: 4.2em;

