import { component$, Slot, useSignal } from "@qwik.dev/core";

/**
 * A real wooden die presses the projected impression into the paper.
 * The mark is readable before the optional image loads, and remains if it fails.
 * Mount/key this component only for a new event, never for routine repaints.
 */
export const StampPress = component$<{ animated?: boolean }>((props) => {
  const toolReady = useSignal(false);

  return (
    <span
      class={[
        "ink-stamp",
        { "ink-stamp--pressing": props.animated && toolReady.value },
      ]}
      aria-hidden="true"
    >
      <span class="ink-stamp__imprint">
        <Slot />
      </span>
      {props.animated && (
        <>
          <span class="ink-stamp__contact-shadow" />
          <img
            class="ink-stamp__tool"
            src="/assets/stamp-press/walnut-stamp.webp"
            width={768}
            height={768}
            alt=""
            draggable={false}
            onLoad$={() => (toolReady.value = true)}
          />
        </>
      )}
    </span>
  );
});
import { component$ } from "@qwik.dev/core";
import { StampPress } from "../ui/stamp-press";
import {
  rubricGradeStampAsset,
  rubricGradeTier,
} from "../../utils/rubric-feedback";

interface GradeStampProps {
  grade: string;
  score: number;
  color: string;
  size?: "compact" | "report";
  animated?: boolean;
  /** Stable result identity: only a new verdict should receive a fresh press. */
  impressionKey?: string | number;
}

/** A complete grade-specific impression, recolored by the active theme. */
export const GradeStamp = component$<GradeStampProps>((props) => {
  const tier = rubricGradeTier(props.grade);
  const asset = rubricGradeStampAsset(props.grade);
  const highest = props.grade.trim().toUpperCase() === "A+";
  return (
    <div
      class={[
        "rubric-grade-stamp",
        `rubric-grade-stamp--${props.size ?? "compact"}`,
        `rubric-grade-stamp--${tier}`,
        { "rubric-grade-stamp--highest": highest },
        { "rubric-grade-stamp--animated": props.animated },
      ]}
      style={{
        color: props.color,
        "--rubric-stamp-image": `url("${asset}")`,
      }}
      role="img"
      aria-label={`Overall grade ${props.grade}, ${props.score} of 100`}
    >
      <StampPress
        key={props.impressionKey ?? `${props.grade}:${props.score}`}
        animated={props.animated}
      >
        <span class="rubric-grade-stamp__mark" />
      </StampPress>
    </div>
  );
});

