const fs = require('node:fs/promises');
const path = require('node:path');
const sharp = require('/home/diogenes/Projects/twyne/node_modules/sharp');
const output = '/home/diogenes/Projects/twyne/public/assets/illuminated-initials';
async function main() {
  const { assets } = JSON.parse(await fs.readFile(path.join(output, 'manifest.json'), 'utf8'));
  const tile = 230, columns = 6, rows = Math.ceil(assets.length / columns), header = 78;
  const panels = [];
  panels.push({ input: Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${tile * columns}" height="${header}"><text x="26" y="36" fill="#35291f" font-family="Georgia" font-size="26">Twyne · Illuminated initials</text><text x="26" y="61" fill="#705c45" font-family="sans-serif" font-size="14">Vermilion, ivory acanthus, antique gold · ${assets.length} original generated illustrations</text></svg>`), left: 0, top: 0 });
  for (let i = 0; i < assets.length; i++) {
    const left = (i % columns) * tile, top = header + Math.floor(i / columns) * tile;
    panels.push({ input: await sharp(path.join(output, assets[i].webp)).resize(198, 198).toBuffer(), left: left + 16, top });
    panels.push({ input: Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${tile}" height="30"><text x="115" y="21" text-anchor="middle" fill="#35291f" font-family="sans-serif" font-size="14">${assets[i].id.toUpperCase()}</text></svg>`), left, top: top + 198 });
  }
  const target = path.join(output, 'contact-sheet.webp');
  await sharp({ create: { width: tile * columns, height: header + tile * rows, channels: 4, background: '#f6efdf' } }).composite(panels).webp({ quality: 93, effort: 5 }).toFile(target);
  console.log(target);
}
