      },
      ({ editor, html }) => {
        const before = html();
        expect(cap(editor)).toBeNull();
        expect(editor.view.dom.dataset.openingInitialMode).toBe("off");
        editor.commands.setOpeningInitial({
          ...DEFAULT_OPENING_INITIAL,

