const fs = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');
const sharp = require('/home/diogenes/Projects/twyne/node_modules/sharp');
const root = '/home/diogenes/Projects/twyne/public/assets/illuminated-initials';
const letters = [...'REDACTED'];
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');

async function sheet(assets, file, title) {
  const size = 210, columns = 6, header = 76;
  const width = size * columns;
  const layers = [{left: 0, top: 0, input: Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${header}"><text x="22" y="34" fill="#30261c" font-family="Georgia" font-size="25">${title}</text><text x="22" y="59" fill="#705c45" font-family="sans-serif" font-size="14">${assets.length} original generated illustrations · vermilion, ivory and antique gold</text></svg>`)}];
  for (const [i, asset] of assets.entries()) {
    const left = i % columns * size;
    const top = header + Math.floor(i / columns) * size;
    layers.push({left: left + 13, top, input: await sharp(path.join(root, asset.webp)).resize(184, 184).toBuffer()});
    const label = asset.variant === 'alternate' ? `${asset.letter} · alternate` : `${asset.letter} · original`;
    layers.push({left, top: top + 183, input: Buffer.from(`<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="27"><text x="105" y="19" text-anchor="middle" fill="#30261c" font-family="sans-serif" font-size="13">${label}</text></svg>`)});
  }
  await sharp({create:{width,height:header + size * Math.ceil(assets.length / columns),channels:4,background:'#f6efdf'}}).composite(layers).webp({quality:94,effort:5}).toFile(path.join(root,file));
}

async function main() {
  const manifest = JSON.parse(await fs.readFile(path.join(root,'manifest.json'),'utf8'));
  const assets = [];
  for (const suffix of ['', '-alt']) for (const letter of letters) {
    const id = letter + suffix;
    const webp = id + '.webp', svg = id + '.svg';
    const bytes = await fs.readFile(path.join(root,webp));
    const metadata = await sharp(bytes).metadata();
    const stats = await sharp(bytes).stats();
    const alpha = stats.channels[3];
    if (metadata.width !== 1024 || metadata.height !== 1024 || !metadata.hasAlpha || alpha.min !== 0 || alpha.max !== 255) throw new Error(`Invalid artwork: ${id}`);
    const wrapper = await fs.readFile(path.join(root,svg),'utf8');
    if (!wrapper.includes(bytes.toString('base64'))) throw new Error(`SVG mismatch: ${id}`);
    assets.push({id,letter:letter.toUpperCase(),variant:suffix?'alternate':'primary',webp,svg,width:1024,height:1024,bytes:bytes.length,alpha:true,alphaRange:[alpha.min,alpha.max],sha256:hash(bytes)});
  }
  const prompts = JSON.parse(await fs.readFile(path.join(root,'generation-prompts.json'),'utf8'));
  const promptMap = new Map(prompts.assets.map(asset => [asset.id,asset]));
  for (const file of ['alternates-b-m-prompts.json','alternates-n-z-prompts.json']) {
    const batch = JSON.parse(await fs.readFile(path.join(root,file),'utf8'));
    for (const asset of batch.assets) promptMap.set(asset.id,asset);
  }
  prompts.assets = assets.map(asset => {
    const prompt = promptMap.get(asset.id);
    if (!prompt?.prompt || !prompt.sourceSha256) throw new Error(`Missing provenance: ${asset.id}`);
    return prompt;
  });
  prompts.reference = 'Original A master; alternate A supplies the complete alternate alphabet style reference';
  await fs.writeFile(path.join(root,'manifest.json'),JSON.stringify({...manifest,assets},null,2)+'\n');
  await fs.writeFile(path.join(root,'generation-prompts.json'),JSON.stringify(prompts,null,2)+'\n');
  const pairs = letters.flatMap(letter => assets.filter(asset => asset.letter === letter.toUpperCase()));
  await sheet(pairs,'contact-sheet.webp','Twyne · Original and alternate illuminated alphabets');
  await sheet(assets.filter(asset => asset.variant === 'alternate'),'alternates-contact-sheet.webp','Twyne · Complete alternate alphabet');
  console.log(`Validated and catalogued ${assets.length} distinct transparent initials and SVG companions.`);
}
main().catch(error => {console.error(error);process.exitCode=1;});

