state.samplePayload = {
  title:'The Art of the Printed Page',
  html:'<p>At the edge of the harbour, the old printing house kept its windows open.</p>' + Array.from({length:16},()=>'<p>The scent of ink drifted into the street, where a reader paused over the first page of a book. Each letter had been placed with care; each line left room for the next thought. A well-made border gives the page a quiet sense of occasion.</p>').join(''),
  layout:{openingInitial:{mode:'illuminated',collection:'alternate',size:'medium'},pageBorder:'botanical',columns:2,columnGap:1.5}
};
state.printHtml = await state.printPage.evaluate(async payload => {
  const {exportHtml} = await import('/src/utils/exchange.ts');
  const {DEFAULT_LAYOUT} = await import('/src/types/index.ts');
  return exportHtml({...payload,layout:{...DEFAULT_LAYOUT,...payload.layout}});
}, state.samplePayload);
await state.printPage.setContent(state.printHtml);
await state.printPage.evaluate(async()=>{
  const {preparePrintedImages} = await import('/src/utils/print-ornaments.ts');
  await preparePrintedImages(document);
  await document.fonts.ready;
});
await state.printPage.pdf({path:'/tmp/twyne-borders-upgraded-print.pdf',printBackground:false,preferCSSPageSize:true});
state.nativeResult = await state.printPage.evaluate(async payload=>{
  const {compileTypstSource} = await import('/src/utils/typst/client.ts');
  const {htmlToTypst} = await import('/src/utils/typst/document.ts');
  const {DEFAULT_LAYOUT} = await import('/src/types/index.ts');
  const result = await compileTypstSource(htmlToTypst(payload.html),{payload:{...payload,layout:{...DEFAULT_LAYOUT,...payload.layout}}});
  let binary='';
  const bytes=new Uint8Array(await result.pdf.arrayBuffer());
  for(let i=0;i<bytes.length;i+=8192) binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
  return {base64:btoa(binary),pages:result.pageCount};
}, state.samplePayload);
require('node:fs').writeFileSync('/tmp/twyne-borders-upgraded-native.pdf',Buffer.from(state.nativeResult.base64,'base64'));
console.log('Printed and compiled upgraded botanical border. Native pages:',state.nativeResult.pages);

