for(let i=0;i<5;i++){const col=i%3,row=Math.floor(i/3);const img=await sharp(`${dir}/option-0${i+1}-1536.avif`).resize(600,400).toBuffer();layers.push({input:img,left:col*620+10,top:row*454+10});const label=Buffer.from(`<svg width="600" height="40"><text x="8" y="28" font-family="Georgia" font-size="23" fill="#201b16">${titles[i]}</text></svg>`);layers.push({input:label,left:col*620+10,top:row*454+412});}
await sharp({create:{width:1860,height:908,channels:3,background:'#f5eddc'}}).composite(layers).png().toFile('/tmp/twyne-landing-five-options.png');
})();
